window.LOR_VERIFY = {"cv": "813_1", "checked": "23.10.2026", "pdf": "813_1_Травма гортани.pdf", "pages": 46, "items": {"m110": {"s": "ok", "sec": "1.4", "page": 8, "q": "S11.0 - Открытая рана, затрагивающая гортань и трахею."}, "m100": {"s": "ok", "sec": "1.4", "page": 8, "q": "S10.0 - Ушиб горла."}, "m101": {"s": "ok", "sec": "1.4", "page": 8, "q": "S10.1 - Другие и неуточненные поверхностные травмы горла."}, "m041": {"s": "ok", "sec": "1.4", "page": 8, "q": "R04.1 – Кровотечение из горла"}, "s1": {"s": "ok", "sec": "1.6, 6", "page": 10, "q": "Главным симптомом является нарушение дыхательной функции, которое может иметь различную степень и может развиваться сразу после травмы или спустя некоторое время в результате нарастания воспалительной инфильтрации, отека или образования гематомы.", "note": "Госпитализация всех и сроки наблюдения — раздел 6."}, "s-airway": {"s": "ok", "sec": "3.2", "page": 25, "q": "Рекомендуется выполнять трахеотомию в сознании пациентам со значительным отеком гортани, особенно при его прогрессировании, с целью недопущения потери проходимости дыхательных путей из-за нарастания явлений стеноза", "note": "Интубация трубкой на размер меньше — комментарий о damage control."}, "s-diag": {"s": "ok", "sec": "2.2", "page": 12, "q": "Рекомендуется проводить ларингоскопию всем пациентам при поступлении в стационар с целью выявления изменения со стороны гортани (см. раздел 1.6 «Клиническая картина»)", "note": "Остальные исследования — раздел 2.4."}, "s-cons": {"s": "ok", "sec": "3.1", "page": 18, "q": "Рекомендуется проводить только консервативное лечение при ссадинах и поверхностных повреждениях кожных покровов, тупых наружных и внутренних травмах гортани, гортаноглотки с развитием отека, ссадин, гематом, без повреждения хрящевого каркаса или с повреждением без смещения хрящевых отломков, при отсутствии нарастания дыхательной недостаточности, гнойно-воспалительных изменений в тканях шеи"}, "c-def": {"s": "ok", "sec": "1.1", "page": 6, "q": "Открытая рана, затрагивающая гортань – это повреждение гортани, возникающее под прямым или опосредованным воздействием травмирующего фактора, который может действовать как снаружи (наружные травмы гортани), так и изнутри (внутренние травмы гортани), сопровождающееся нарушением целостности кожных покровов, слизистой оболочки и приводящее к нарушению целостности и функции данного органа. Ушиб глотки, гортани – это закрытое механическое повреждение тканей и структур глотки, гортани без видимого нарушения целостности наружных кожных покровов и слизистых оболочек, возникающее при воздействии тупым предметом извне или изнутри, сопровождающееся разрывом мелких сосудов с последующим кровоизлиянием."}, "c-etio": {"s": "ok", "sec": "1.2", "page": 6, "q": "Причиной открытой раны шеи с повреждением гортани является воздействие повреждающего фактора, приводящее к повреждению кожного покрова, и может встречаться в условиях мирного и военного времени. Чаще всего встречается при ножевых и огнестрельных ранениях. Причинами наружных тупых травм глотки и гортани могут являться: удар тупого предмета или кулака в шею, автомобильная авария, спортивная травма, попытка удушения, зачастую сопровождаются переломом ее хрящей и подъязычной кости, отрывом гортани, разрывом голосовых складок, а также сочетанным повреждением окружающих гортань анатомических образований. Внутренняя травма гортани и глотки сопровождающаяся кровотечением ( кровотечение из горла) чаще носит ятрогенный характер (интубация, ИВЛ) или является следствием попадания инородного тела (рыбья кость, куски пищи, зубные протезы и др.). 6  Другими причинами кровотечения из горла могут являться злокачественные опухоли данной локализации, последствия оперативных вмешательств и манипуляций в глотке и гортани. Ранения гортани и глотки возможны при проведении любой манипуляции в данной зоне, в том числе во время эндоскопических исследований и хирургических вмешательств [68, 69]. Наружные травмы шеи чаще встречаются в условиях боевых действий и в большинстве случаев являются множественными и сочетанными. В то время как внутренние травмы глотки и гортани чаще изолированные, возникают при повреждении органа через естественные пути. Травма гортани может сопровождаться переломом подъязычной кости, хрящей гортани и трахеи, отрывом гортани от трахеи или подъязычной кости, разрывом голосовых связок, смещением черпаловидных хрящей, парезом гортани. Развиваются кровоизлияния в подкожную клетчатку, мышцы, формируются гематомы, приводящие к сдавлению дыхательных путей, что может приводить к развитию дыхательной недостаточности.", "note": "Длинный фрагмент раздела 1.2."}, "c-kids": {"s": "ok", "sec": "1.2", "page": 7, "q": "Анатомическое строение гортани у детей отличается от такового у взрослых. Гортань у взрослых имеет более жесткий каркас и предрасположена к перелому от тупой травмы. Напротив, гортань у детей состоит из гибких хрящевых структур, устойчивых к перелому. Более того, подслизистый слой гортани у детей слабо прикреплен к подлежащей надхрящнице. Однако это слабое крепление и упругость предрасполагают ребенка к более серьезным повреждениям мягких тканей с риском возникновения массивного отека и образования гематомы. Даже минимальная травма может предрасполагать детей к повреждению слизистой оболочки и разрыву задней стенки трахеи"}, "c-class": {"s": "ok", "sec": "1.5", "page": 8, "q": "Классификация травм гортани [28,33]: - по этиологии: механические (в том числе ятрогенные), огнестрельные, химические, термические; - по механизму действия повреждающего фактора травмы и раны гортани разделяют на: наружные, внутренние, тупые, острые (колотые, резаные); 8  - по наличию кожной раны: открытая, закрытая; - по факту проникновения в полость гортани: проникающие, непроникающие; - по наличию или отсутствию повреждений других органов – изолированные, сочетанные."}, "sch-1": {"s": "ok", "sec": "1.5", "page": 9, "q": "первая - незначительные эндоларингеальные гематомы без повреждения слизистой оболочки, хрящей"}, "sch-2": {"s": "ok", "sec": "1.5", "page": 9, "q": "вторая - отек, гематома, незначительные повреждения слизистой оболочки без обнажения хряща или перелом хряща без смещения"}, "sch-3": {"s": "ok", "sec": "1.5", "page": 9, "q": "третья - массивный отек, большие разрывы слизистой оболочки, обнаженный хрящ, перелом хряща со смещением или неподвижность голосовых складок"}, "sch-4": {"s": "ok", "sec": "1.5", "page": 9, "q": "четвертая – плюс к 3 группе серьезные повреждения передних отделов гортани, нестабильные переломы, две или более линии перелома или тяжелые травмы слизистой оболочки"}, "sch-5": {"s": "ok", "sec": "1.5", "page": 9, "q": "пятая – полный отрыв гортани от трахеи"}, "c-class-gun": {"s": "ok", "sec": "1.5", "page": 9, "q": "Огнестрельные ранения гортани делятся на: касательные ранения одного или нескольких хрящей гортани при отсутствии проникновения в ее полость или в один из ее анатомических отделов (преддверие, голосовая щель, подскладковое пространство) без существенного нарушения дыхательной функции; проникающие слепые или сквозные ранения гортани с нарушением разной степени дыхательной и голосовой функций без сочетанного повреждения окружающих анатомических образований; проникающие слепые или сквозные ранения гортани с нарушением разной степени дыхательной и голосовой функций с наличием повреждений окружающих анатомических образований (пищевода, сосудисто-нервного пучка, позвоночника). Классификация травм глотки [28,33]: Травмы глотки делятся на: наружные и внутренние. По этиологическому фактору на: бытовые, производственные, военного времени. По травмирующему фактору: тупые травмы; колото-резаные раны; огнестрельные раны; химические ожоги; термические ожоги; инородные тела. По отделу глотки: травмы носоглотки, ротоглотки и гортаноглотки. По распространенности повреждения – изолированные, сочетанные."}, "c-clin": {"s": "ok", "sec": "1.6", "page": 10, "q": "Главным симптомом является нарушение дыхательной функции, которое может иметь различную степень и может развиваться сразу после травмы или спустя некоторое время в результате нарастания воспалительной инфильтрации, отека или образования гематомы. Нарушения голоса (дисфония, афония) в той или иной степени возникают при всех травмах гортани и особенно выражены при повреждении голосового отдела. Болевой синдром может иметь самую различную интенсивность от ощущения дискомфорта (инородного тела) до выраженной боли в проекции гортани и глотки. Нарушение глотания (дисфагия) возникает в результате нарушения разделительной функции гортани при повреждении входа в гортань, парезах гортани, патологии глотки. Кашель не всегда сопровождает травмы гортани. Как правило, он возникает при попадании инородного тела в гортань, при внутреннем кровотечении или развитии острой воспалительной реакции. Наличие подкожной эмфиземы в области шеи говорит о проникающем характере повреждения гортани или трахеи. Эмфизема способна быстро распространяться на шею, грудь, средостение. Кровотечение при повреждении полых органов и мягких тканей шеи считают угрожающим для жизни при открытой травме крупных сосудов и развитии внутреннего кровотечения, вызывающего аспирацию крови или образование гематомы, суживающей просвет гортани и трахеи. Проникающая резаная, колотая или огнестрельная рана имеет характерный вид: на выдохе из нее выходит пузырящийся кровавой пеной воздух, а на вдохе происходит засасывание воздуха в рану с характерным шипящим звуком. Внутренние травмы гортани могут сопровождаться кровотечением (кровотечение из горла), которое проявляется кровохарканьем, истечением крови изо рта. При повреждении гортанных нервов отмечается нейропатический парез гортани.", "note": "Длинный фрагмент раздела 1.6."}, "c-clin-pharynx": {"s": "ok", "sec": "1.6", "page": 10, "q": "Внутренние повреждения глотки чаще протекают легче, чем наружные. Отмечается характерный анамнез, больные обычно указывают место повреждения в глотке и что этому предшествовало (диагностические и лечебные эндоскопические вмешательства, прием пищи, интубация трахеи при наркозе). Сразу после травмы появляется боль в горле, усиливающаяся 10  при глотании, нарушается глотание, возможно кровотечение из горла при разрыве слизистой оболочки и нарушение дыхания в результате нарастания отека"}, "c-clin-kids": {"s": "ok", "sec": "1.6", "page": 11, "q": "У детей респираторные симптомы при повреждении гортани и трахеи могут развиваться гораздо быстрее или быть более выраженными из-за меньших размеров дыхательных путей и анатомических особенностей [12]. В то же время проявление тупых травм гортани и трахеи у детей может быть неявным и может имитировать другие распространенные детские респираторные заболевания"}, "d-crit": {"s": "ok", "sec": "2", "page": 11, "q": "Критерии установления диагноза/состояния: 1. Анамнез, не позволяющий исключить получение открытой или закрытой травмы шеи. Появление характерных жалоб после момента травмы – боль, затруднение дыхания, изменения голоса, затруднение глотания, кровотечение, одышка. Стридор (свистящее дыхание): на вдохе — подразумевает обструкцию на уровне надскладкового отдела гортани, которая может быть вызвана отеком или гематомой; стридор на выдохе, как правило, возникает из-за обструкции подскладкового отдела гортани, например, при травме трахеи; двухфазный стридор (на вдохе и на выдохе) подразумевает повреждение голосовой щели. Выявление соответствующих травматических изменений кожных покровов - открытой раны или отека и гематомы в области шеи, наличие подкожной эмфиземы. Исчезновение крепитации в гортани — при пальпации гортани и перемещении ее в стороны обычно ощущается ―щелчок‖. Исчезновение этого ―щелчка‖ может произойти из-за фиксации гортани или ее повреждения. Появление на выдохе из раны пузырящейся кровавой пены, крови в слюне. При видеоларингоскопии гортани, гортаноглотки – отек, кровоизлияние, гематома, разрыв слизистой оболочки, деформация просвета голосовой щели, нарушение подвижности голосовых складок. По данным компьютерной томографии (КТ) верхних дыхательных путей и шеи - появление деформации контуров шеи, наличие эмфиземы, перелома хрящевого каркаса гортани, изменения в области просвета гортани, 11  раневой канал и наличие инородных тел при огнестрельной ране, нарушение пассажа рентгеноконтрастного препарата (диагностического радиофармацевтического средства) при ранении глотки и пищевода.", "note": "Длинный фрагмент критериев раздела 2."}, "d-anam": {"s": "ok", "sec": "2.1, 2.2", "page": 12, "q": "При травмах гортани пострадавшие могут предъявлять жалобы на боль, отек мягких тканей шеи, нарушение дыхания, наружное кровотечение, возможно развитие кровотечения из горла. При сборе анамнеза следует определять возможный механизм травмы и время, прошедшее с ее получения, выявлять наличие или отсутствие жалоб и их динамику. В связи с тем, что пациент может находится в бессознательном состоянии, выяснение анамнеза и обстоятельств травмыпри возможности проводить у родственников или сопровождающих лиц [14, 15]. 2.2 Физикальное обследование Основные принципы первичной оценки в протоколах расширенного жизнеобеспечения при травме (Advanced Trauma Life Support, ATLS) применимы к травме шеи, так же, как и к любому другому повреждению"}, "d-laryngo": {"s": "ok", "sec": "2.2", "page": 12, "q": "Рекомендуется проводить ларингоскопию всем пациентам при поступлении в стационар с целью выявления изменения со стороны гортани (см. раздел 1.6 «Клиническая картина») [9, 15, 17-24]. Уровень убедительности рекомендаций С (уровень достоверности доказательств - 5). Комментарий: проведение ларингоскопии (непрямой ларингоскопии при помощи гортанного зеркала) является обязательной диагностической процедурой при осмотре пациентов 12 лет и старше с травмами гортани и глотки, как наиболее доступный рутинный метод визуальной оценки состояния слизистой оболочки гортани. При осмотре детей дошкольного и младшего школьного возраста проведение данного метода зачастую не представляется возможным по причине эмоциональной лабильности пациента и выраженного глоточного рефлекса"}, "d-wound": {"s": "ok", "sec": "2.2", "page": 12, "q": "Рекомендуется производить оценку локализации раны, размеры, глубину и состояние краев, взаимоотношение с сосудами и нервами у всех пациентов с целью исключения наличия инородных тел, наружного или горлового кровотечения, повреждения дыхательных путей"}, "d-palp": {"s": "ok", "sec": "2.2", "page": 13, "q": "Рекомендуется всем пациентам при осмотре проводить пальпацию шеи и грудной клетки с целью исключения подкожной эмфиземы"}, "d-video": {"s": "ok", "sec": "2.4", "page": 14, "q": "Рекомендуется всем пациентам выполнять видеоларингоскопию с использованием гибких и ригидных эндоскопов ( ларингофарингоскопы жесткие, видеоларингоскопы гибкие) с углом обзора 70 и 90 градусов [9, 20, 22, 28]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5) Комментарий: видеоларингоскопия позволяет оценить состояние слизистой оболочки, наличие или отсутствие ее повреждений, наличие и распространенность отека в области гортани и гортаноглотки, состояние голосовой щели и подвижность голосовых складок, состояние подскладкового отдела гортани и трахеи. При наличии раневого отверстия в области гортани или трахеи возможен ретроградный осмотр. У детей фиброларингоскопия является предпочтительным методом для визуальной оценки состояния гортани"}, "d-micro": {"s": "ok", "sec": "2.4", "page": 14, "q": "Рекомендуется выполнять микроларингоскопию всем пациентам (2-5 группа по классификации тяжести травмы Schaeferс целью уточнения диагностики и выбора метода и объема лечения) [9, 15, 28, 36]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5) Комментарий: данное исследование может быть выполнено у взрослых и детей после достижения постоянной проходимости дыхательных путей и позволяет более детально провести осмотр гортани, оценить состояние перстнечерпаловидного сочленения, слизистой оболочки, хрящевого каркаса, и помочь в выборе метода и объема реконструктивно-восстановительного вмешательства."}, "d-strobe": {"s": "ok", "sec": "2.4", "page": 15, "q": "Рекомендуется выполнять ларингоскопию с использованием стробоскопа и электромиографию гортани (электромиография накожная)всем пациентам с травмами гортани для оценки подвижности голосовых складок (при наличии соответствующего оборудования) [9]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5) Комментарий: выполняется для объективизации степени нарушения подвижности голосовых складок."}, "d-us": {"s": "ok", "sec": "2.4", "page": 15, "q": "Рекомендуется проведение ультразвукового исследования (УЗИ) гортани пациентам детского возраста с травмой гортани [8, 37]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 4) Комментарий: УЗИ не требует специальной подготовки и хорошо визуализирует подвижность голосовых связок и черпаловидных хрящей, асимметричное расположение черпаловидных хрящей, утолщение голосовых связок, переломы щитовидного хряща и гематомы этой области. УЗИ гортани рекомендуется как неинвазивное исследование в дополнение к ларингоскопии"}, "d-ct-vasc": {"s": "ok", "sec": "2.4", "page": 13, "q": "Рекомендуется проводить спиральную компьютерную томографию (СКТ) шеи и/или компьютерную томографию (КТ) шеи с внутривенным болюсным контрастированием при подозрении на повреждение сосудов с целью оценки степени повреждения"}, "d-ct-note": {"s": "ok", "sec": "2.4", "page": 14, "q": "Выполнение стандартной рентгенографии мягких тканей шеи, гортани и трахеи диагностически мало значимо, поскольку позволяет обнаружить только отек, подкожную эмфизему или перелом подъязычной кости, в то время как компьютерная томография обеспечивает визуализацию переломов гортани и травмы мягких тканей [34]. Данные исследования позволяют оценить состояние анатомических структур шеи (обращают внимание на состояние хрящевого каркаса гортани, подъязычной кости, наличие и ход раневого канала, наличие инородных тел, вовлеченность сосудов шеи, наличие и распространенность эмфиземы"}, "d-ct-eso": {"s": "ok", "sec": "2.4", "page": 13, "q": "Рекомендуется проводить компьютерную томографию (КТ) пищевода с пероральным контрастированием всем пациентам с травмой шеи при поступлении в стационар при подозрении на повреждение глотки, пищевода"}, "d-eso": {"s": "ok", "sec": "2.4", "page": 15, "q": "Рекомендуется выполнять эзофагоскопию пациентам с проникающим ранением гортани или глотки с целью исключения повреждения пищевода"}, "d-spine": {"s": "ok", "sec": "2.4", "page": 15, "q": "во всех случаях травмы гортани исключать повреждение шейного отдела позвоночника с целью предупреждения сопутствующей патологии, способствующей утяжелению состояния пациента [22]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5). Комментарий: сопутствующие повреждения шейного отдела позвоночника могут значительно утяжелять состояние пациента. Выявление повреждения позвоночника требует немедленной консультации профильного специалиста."}, "d-mri-no": {"s": "ok", "sec": "2.4", "page": 16, "q": "Не рекомендуется пострадавшим с осколочными и пулевыми ранениями выполнять МРТ исследования в связи с возможным наличием инородных металлических тел металлической в ране с целью недопущения их неконтролируемого смещения в процессе исследования"}, "d-lab": {"s": "ok", "sec": "2.3", "page": 13, "q": "Рекомендуется выполнять общий (клинический) анализ крови пациентам с кровопотерей или подозрении на произошедшую кровопотерю для оценки возможной анемии и объема кровопотери [28, 30]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5). Рекомендуется выполнять ориентировочное исследование системы гемостаза (коагулограмму) всем пациентам для оценки нарушений гемостаза (и при необходимости для подготовки к оперативному вмешательству"}, "d-spo2": {"s": "ok", "sec": "2.5", "page": 16, "q": "Рекомендуется проведение пульсоксиметрии детям с признаками стеноза верхних дыхательных путей с целью оценки степени дыхательной недостаточности и необходимости назначения оксигенотерапии"}, "d-cult": {"s": "ok", "sec": "2.5", "page": 16, "q": "Рекомендуется проведение микробиологического (культурального) исследования гнойного отделяемого из раны на аэробные и факультативно-анаэробные микроорганизмы с определением чувствительности микроорганизмов к антимикробным химиотерапевтическим препаратам пациентам с ранением гортани или глотки с целью назначения эффективной терапии"}, "t-princ": {"s": "ok", "sec": "3", "page": 16, "q": "Лечение пациентов с травмой гортани и глотки подчиняется следующим принципам независимо от выбранной тактики: • Восстановление и поддержание проходимости дыхательных путей. • Остановка кровотечения и восполнение кровопотери при необходимости. • Проведение мероприятий по профилактике травматического шока. 16  •Проведение противоотечной, антибактериальной, дезинтоксикационной, противовоспалительной терапии."}, "t-airway": {"s": "ok", "sec": "3", "page": 17, "q": "Рекомендуется уделять первоочередное внимание проходимости дыхательных путей при оказании помощи пациентам с повреждением гортани, гортаноглотки, с целью своевременной диагностики их обструкции или потенциальной обструкции, а также предотвращению аспирации содержимым ротоглотки"}, "tg-1": {"s": "ok", "sec": "3", "page": 17, "q": "1 группа (обязательное проведение гибкой эндоскопии гортани) - легкие травмы, как правило, поддаются медикаментозному лечению и не требуют хирургического вмешательства. Могут быть полезны: кортикостероиды системного действия, антибактериальные препараты системного действия препараты для лечения язвенной болезни желудка и двенадцатиперстной кишки и гастроэзофагеальной рефлюксной болезни ( ГЭРБ)и увлажнение воздуха, голосовой покой;"}, "tg-2": {"s": "ok", "sec": "3", "page": 17, "q": "2 группа (дополнительно должны быть выполнены прямая ларингоскопия и эзофагоскопия) – наблюдение в динамике, поскольку со временем повреждения могут ухудшаться или прогрессировать. Иногда при таких травмах может потребоваться трахеотомия. Также могут быть полезны: кортикостероиды системного действия , антибактериальные препараты широкого спектра действия, и препарататы для лечения язвенной болезни желудка и двенадцатиперстной кишки и гастроэзофагельной рефлюксной болезни ( ГЭРБ) реф увлажнение воздуха, голосовой покой;"}, "tg-3": {"s": "ok", "sec": "3", "page": 17, "q": "2 группа (прямая ларингоскопия или эзофагоскопия должна проводиться в операционной) - часто требуется выполнение трахеотомии, как правило, потребуется хирургическое вмешательство при: разрыве передней комиссуры, обширных рваных ранах гортани, разрывах голосовых складок, неподвижности голосовых складок, обнажение хряща, переломах со смещением хряща, подвывихах или дислокации черпаловидного хряща;", "note": "В КР эта группа обозначена «2», хотя по описанию соответствует 3-й группе классификации Schaefer."}, "tg-4": {"s": "ok", "sec": "3", "page": 17, "q": "3 группа (обязательно проводятся прямая ларингоскопия и эзофагоскопия) - всегда требуется трахеотомия, хирургическое лечение таких повреждений потребует установки стента для сохранения целостности гортани;"}, "tg-5": {"s": "ok", "sec": "3", "page": 17, "q": "4 группа (у этих пациентов наблюдается тяжелая дыхательная недостаточность и поэтому эндоскопическое обследование откладывается до тех пор, пока не будут 17  проходимы дыхательные пути) - повреждения на уровне перстневидно хряща, перстнещитовидной мембраны, перстнетрахеального соединения - трахеотомия необходима для восстановления проходимости дыхательных путей, но может быть очень сложной из-за измененной анатомии. Выполняют ларинготрахеопластику для восстановления гортанно-трахеальной области."}, "t-cons": {"s": "ok", "sec": "3.1", "page": 18, "q": "Рекомендуется проводить только консервативное лечение при ссадинах и поверхностных повреждениях кожных покровов, тупых наружных и внутренних травмах гортани, гортаноглотки с развитием отека, ссадин, гематом, без повреждения хрящевого каркаса или с повреждением без смещения хрящевых отломков, при отсутствии нарастания дыхательной недостаточности, гнойно-воспалительных изменений в тканях шеи [9, 28, 39]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5). Комментарий: при консервативном лечении необходимо проводить обработку ссадин или других поверхностных повреждений кожных покровов антисептиками с последующим наложением асептической повязки. При стабильном состоянии пациента данный вид травм можно лечить с помощью симптоматической терапии."}, "t-antisept": {"s": "ok", "sec": "3.1", "page": 18, "q": "Рекомендуется назначение антисептиков и дезинфицирующих средств (местных антисептических препаратов) пациентам с травмой гортани при повреждении кожных покровов с признаками инфицирования раны или высоким риском ее инфицирования с целью предотвращения развития гнойного воспаления [9, 28, 39]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5). Комментарии: Выраженными антимикробными свойствами обладают препараты группы четвертичных аммониевых соединений (бензилдиметил[3(миристоиламино)пропил]аммоний хлорид моногидрат)(АТХ D08AJ), группы препаратов йода (повидон-йод**(D08AG02)), группы бигуанидов и амидинов (хлоргексидин**(D08AC02)). Возможно применение данных препаратов во взрослом и детском возрасте. Кратность обработки раны зависит от выраженности воспаления и характера экссудата. Рана обрабатывается до разрешения инфекции или начала ее эпителизации"}, "t-inh": {"s": "ok", "sec": "3.1", "page": 19, "q": "Рекомендуется назначать ингаляторное введение лекарственных препаратов и кислорода пациентам с признаками стеноза верхних дыхательных путей с целью уменьшения отека и воспаления в тканях гортани, улучшения оксигенации крови [9, 22, 28]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5). Комментарии: после получения травмы и на этапах эвакуации в стационар целесообразно давать прохладный кислород через маску для ингаляций кислорода. Ингаляции кортикостероидов (ATX RO3BA): будесонида** (АТХ R03BA02) раствор для ингаляций взрослым 1,0 мг 1-2 раза в день, курс 5-8 процедур, детям – старше 6 месяцев суспензия для ингаляций 0,25- 0,5мг 1-2 раза в день курсом 5 процедур. Длительность ингаляции составляет обычно 10 минут, перерыв между ингаляциями с препаратами различного действия составляет около 30 минут."}, "t-edema": {"s": "ok", "sec": "3.1", "page": 19, "q": "Рекомендуется назначать противоотечную терапию пострадавшим с открытой и закрытой травмой гортани с целью уменьшения посттравматического отека в области гортани, гортаноглотки [7, 9, 22, 28]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5). Комментарии: целесообразно парентеральное введение кортикостероидов системного действия и диуретиков"}, "t-voice": {"s": "ok", "sec": "3.1", "page": 19, "q": "Рекомендуется назначать ограничение голосовой нагрузки (не кричать, не шептать сроком не менее 2-х дней) пострадавшим с травмой гортани с целью уменьшения отека гортани и ускорения разрешения реактивных явлений [22, 28]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5). Комментарии: необходимо создать охранительный режим (голосовой режим), рекомендовать больному при травме гортани - полный голосовой покой сроком на 1 – 2 суток, затем ограничение любой голосовой нагрузки. Также необходимо прекратить прием острой, соленой, горячей, холодной пищи, спиртных напитков, курение."}, "t-ppi": {"s": "ok", "sec": "3.1", "page": 19, "q": "Рекомендуется назначать прием препаратов для лечения язвенной болезни желудка и двенадцатиперстной кишки и ГЭРБ (Код АТХ: A02BX) пациентам с раной или 19  воспалительными изменениями слизистой оболочки гортани или гортаноглотки с целью предотвращения воздействия желудочного содержимого на раневую поверхность или воспаленную слизистую оболочку гортани и гортаноглотки"}, "t-ngt": {"s": "ok", "sec": "3.1", "page": 24, "q": "Рекомендуется устанавливать зонд назогастральный (питательный зонд) и назначать лечебное парентеральное питание при ранении гортаноглотки, пищевода, выраженном отеке в области гортаноглотки, невозможности питания через естественные пути в целях недопущения попадания пищи в дыхательные пути"}, "t-pain": {"s": "ok", "sec": "3.1", "page": 20, "q": "Рекомендуется назначать анальгетики, нестероидные противовоспалительные и противоревматические препараты, пострадавшим с травмой гортани и глотки с целью уменьшения отека и болевого синдрома [7; 28; 34; 41]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5). Комментарии: С целью уменьшения выраженности боли используются препараты из группы другие анальгетики и антипиретики (АТХ: N02B) и группы нестероидные противовоспалительные и противоревматические препараты (АТХ: M01A) отдельно или в комбинациях [41; 42]. Рекомендуется применять комбинацию нестероидных противовоспалительных препаратов (НПВП) (АТХ: M01A) и анилидов (парацетамол**(ATX: N02BE01)), а также пиразолоны (метамизол натрия (АТХ: N02BB02)) для купирования болевого синдрома у взрослых и детей, в том числе в послеоперационном периоде (Таблицы 1, 2) [43, 44]. У детей применение НПВП (АТХ: M01A) ограничивается ибупрофеном**(ATX: M01AE01) с 3 мес. для суппозиториев ректальных и суспензии для приема внутрь, с 6 лет для таблеток и с 12 лет для капсул и кетопрофеном**(ATX: M01AE03) с 6 лет для гранул для приема внутрь и с 15 лет для форм для парентерального введения. В амбулаторной практике при лечении детей следует воздержаться от применения препаратов метамизола натрия (АТХ: N02BB02), а в стационарной практике использовать их только в случае недоступности других анальгетиков (Код АТХ: N02), разрешенных к применению у детей, по причине рисков развития серьезных нежелательных явлений."}, "an-par": {"s": "ok", "sec": "3.1", "page": 20, "q": "Таблица 1. Рекомендованные дозы и режимы применения анальгетической и противоотечной терапии у взрослых при травмах гортани. Препарат Парацетамол** (АТХ: N02BE01) Диклофенак** Разовая доза 1 г в/в инфузия в течение 15 мин.", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страниц 20–21.", "img": [20, 21]}, "an-dicl": {"s": "ok", "sec": "3.1", "page": 20, "q": "75 мл в/м", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страниц 20–21. В КР разовая доза записана «75 мл в/м».", "img": [20, 21]}, "an-ketor": {"s": "ok", "sec": "3.1", "page": 21, "q": "(ATX: M01AB05) Кеторолак** (ATX: M01AB15)", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страниц 20–21.", "img": [20, 21]}, "an-ketop": {"s": "ok", "sec": "3.1", "page": 21, "q": "Кетопрофен** (ATX: M01AE03)", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страниц 20–21.", "img": [20, 21]}, "an-lorn": {"s": "ok", "sec": "3.1", "page": 21, "q": "Лорноксикам (ATX: M01AC05)", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страниц 20–21.", "img": [20, 21]}, "an-dexk": {"s": "ok", "sec": "3.1", "page": 21, "q": "Декскетопрофен** (ATX: M01AE17)", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страниц 20–21.", "img": [20, 21]}, "an-met": {"s": "ok", "sec": "3.1", "page": 21, "q": "500-1000 мг в/в, в/м", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страниц 20–21.", "img": [20, 21]}, "ak-par-iv": {"s": "ok", "sec": "3.1", "page": 21, "q": "Таблица 2. Рекомендованные дозы и режимы применения анальгетической и противоотечной терапии у детей при травмах гортани. Препарат Парацетамол** (в/в) (ATX: N02BE01) Парацетамол** (per os)суспензия (ATX: N02BE01) Парацетамол** (свечи ректально) (ATX: N02BE01) Ибупрофен** (per os) (ATX: M01AE01) Ибупрофен** (свечи ректально) (ATX: M01AE01) Кетопрофен** (ATX: M01AE03) Кетопрофен** (per os) (ATX: M01AE03) Разовая доза в/в инфузия в течение 15 минут: 10-50 кг – 15 мг/кг; <10 кг – 7,5 мг/кг > 50 кг – 1000 мг Новорожденным до 1 месяца противопоказан!", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страниц 21–22. Максимальные суточные дозы заданы для пересекающихся весовых групп «33–50 кг» и «10–50 кг».", "img": [21, 22]}, "ak-par-po": {"s": "ok", "sec": "3.1", "page": 21, "q": "Парацетамол** (per os)суспензия", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страниц 21–22.", "img": [21, 22]}, "ak-par-rect": {"s": "ok", "sec": "3.1", "page": 21, "q": "Парацетамол** (свечи ректально) (ATX: N02BE01) Ибупрофен** (per os) (ATX: M01AE01) Ибупрофен** (свечи ректально) (ATX: M01AE01) Кетопрофен** (ATX: M01AE03) Кетопрофен** (per os) (ATX: M01AE03) Разовая доза в/в инфузия в течение 15 минут: 10-50 кг – 15 мг/кг; <10 кг – 7,5 мг/кг > 50 кг – 1000 мг Новорожденным до 1 месяца противопоказан! 10-15 мг/кг 10-14 лет – 350-500 мг", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страниц 21–22.", "img": [21, 22]}, "ak-ibu-po": {"s": "ok", "sec": "3.1", "page": 21, "q": "Ибупрофен** (per os)", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страниц 21–22.", "img": [21, 22]}, "ak-ibu-rect": {"s": "ok", "sec": "3.1", "page": 21, "q": "Ибупрофен** (свечи ректально)", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страниц 21–22.", "img": [21, 22]}, "ak-ketop-iv": {"s": "ok", "sec": "3.1", "page": 21, "q": "с 15 лет – 100 мг в/в, в/м", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страниц 21–22.", "img": [21, 22]}, "ak-ketop-po": {"s": "ok", "sec": "3.1", "page": 21, "q": "гранулы для приготовления раствора для приема внутрь >6 лет – 40 мг", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страниц 21–22.", "img": [21, 22]}, "ak-met": {"s": "ok", "sec": "3.1", "page": 21, "q": "Метамизол натрия (АТХ: N02BB02) с 15 лет – 500-1000 мг в/в, в/м; 3 мес - 1 год – 50100мг/10кг в/м 8-12 ч с 15 лет - 2 г; 21  3 сут.", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страниц 21–22.", "img": [21, 22]}, "t-abx": {"s": "ok", "sec": "3.1", "page": 22, "q": "Рекомендуется системная антибактериальная терапия всем пациентам с открытой раной или при наличии осложнений, сочетанных повреждениях с целью профилактики и лечения инфекционных осложнений [7, 9, 28, 33, 37]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5). Комментарий: Близость гортани к ротоглотке увеличивает риск инфицирования травмированных тканей гортани. Необходимо назначать антибактериальные препараты системного действия [7]. Назначают препараты цефалоспоринового ряда (цефалоспорины третьего поколения): цефотаксим** (Код АТХ:J01DD01) или цефтриаксон** (Код АТХ: J01DD04), инфузионную противомикробную терапию метронидазолом**(код ATX: J01XD01 ), при распространении эмфиземы в средостение и риске возникновения медиастинита препараты группы карбапенемы: меропенем** (Код АТХ J01DH02). Доза, кратность и длительность курса лечения вариабельны, выбираются в зависимости от клинической ситуации."}, "ab-ctx": {"s": "ok", "sec": "3.1", "page": 22, "q": "Таблица 4. Рекомендуемые антибактериальные препараты системного действия (ATХ: J01 (АБП)) при травмах шеи Препарат Цефотаксим** (АТХ: J01DD01) Цефтриаксон** (ATX: J01DD04) Метронидазол** (АТХ: J01XD01) Разовая доза В/в или в/м. Взрослые и дети >12 лет (масса тела >50 кг): 1 г; дети <12 лет (масса тела <50 кг): 50-75 мг/кг; новорожденные: 25 мг/кг", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страницы 22.", "img": [22]}, "ab-ctr": {"s": "ok", "sec": "3.1", "page": 22, "q": "Взрослые: 1-2 г в/в, в/м; дети 2 мес.-12 лет: 20-100 мг/кг в/в, в/м; новорожденные, ( с 15 дней), грудные дети и дети младшего возраста 20-80 мг/кг в/в, в/м", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страницы 22.", "img": [22]}, "ab-mtz": {"s": "ok", "sec": "3.1", "page": 22, "q": "В/в капельно. Скорость введения 5 мл/мин. >12 лет: 500 мг; <12 лет: 7,5 мг/кг", "note": "Таблица в PDF разорвана при извлечении текста. Сверено по изображению страницы 22.", "img": [22]}, "t-tetanus": {"s": "ok", "sec": "3.1", "page": 22, "q": "Рекомендуется введение вакцины для профилактики столбняка всем ациентам при травмах гортани с нарушением целости кожных покровов и слизистых оболочек при попадании загрязненных частиц в рану [33,37]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5) 22  Комментарии: Экстренную иммунопрофилактику столбняка следует проводить как можно раньше и вплоть до 20 дня с момента получения травмы, учитывая длительность инкубационного периода при заболевании столбняком. Экстренная профилактика столбняка заключается специфической иммунопрофилактике анатоксином столбнячным** (АТХ: J07AM01), иммуноглобулином человека противостолбнячным** (АТХ: J06BB02) или сывороткой противостолбнячной лошадиной очищенной концентрированной жидкой (АТХ: J06AA02 Антитоксин столбнячный**) согласно инструкции по применению."}, "t-hemost": {"s": "ok", "sec": "3.1", "page": 23, "q": "Рекомендуется назначение гемостатических средств всем пациентам с травмой гортани при наличии признаков наружного кровотечения или кровотечения из горла с целью его остановки [21, 25, 28]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5). Комментарий: небольшие наружные кровотечения при ранениях гортани и трахеи останавливают наложением асептической давящей повязки и назначением гемостатических средств. С этой целью применяются препараты из групп другие гемостатические средства системного действия (этамзилат**(АТХ: B02BX01)) и антифибринолитические средства (транексамовая кислота**(АТХ: B02AA02), аминокапроновая кислота**(АТХ: B02AA01)). Этамзилат**(АТХ: B02BX01) для остановки кровотечения взрослым вводится в/в или в/м 250–500 мг, после чего каждые 4-6 часов по 250 мг; детям 10-15 мг/кг/сутки за 34 приема – в течение 5-10 дней. Транексамовая кислота**(АТХ: B02AA02) вводится в/в капельно или струйно медленно, скорость введения 1 мл/мин (50 мг/мин). Назначается в дозе 10-15 мг/кг каждые 6-8 часов у взрослых и 20 мг/кг/сутки у детей старше 1 года до остановки кровотечения. Аминокапроновая кислота**(АТХ: B02AA01) применяется в/в капельно. Взрослым в течение первого часа вводят 4-5 г препарата, в случае продолжающегося кровотечения – по 1 г/час не более 8 часов до остановки кровотечения; при необходимости инфузии повторяют каждые 4 часа; максимальная суточная доза 30 г. Детям – 100 мг/кг массы тела в первый час, затем – 33 мг/кг/ч; максимальная суточная доза – 18,0 г/м2 поверхности тела (до 1 года – 3 г; 2-6 лет – 3-6 г; 7-10 лет – 6-9 г; от 10 лет – 23  как для взрослых). При острых кровопотерях: детям до 1 года – 6 г; 2-4 лет – 6-9 г; 58 лет – 9-12 г; 9-10 лет – 18 г. Длительность терапии – 3-14 дней.", "note": "Длинный фрагмент с дозами трёх препаратов."}, "t-surg-ind": {"s": "ok", "sec": "3.2", "page": 24, "q": "Рекомендуется проводить хирургическое лечение пациентам, имеющим следующие проявления травмы: стеноз гортани в стадии декомпенсации, кровотечение, наличие открытой раны, загрязнение раны, наличие инородных тел, нежизнеспособных тканей, потеря мягких тканей, дефицит кожи, наличие выраженной или нарастающей эмфиземы, перелом хрящевого каркаса гортани со смещением хрящевых фрагментов, суживающих просвет гортани с целью своевременного предупреждения прогрессирования патологии, представляющей угрозу жизни"}, "t-trach": {"s": "ok", "sec": "3.2", "page": 25, "q": "Рекомендуется выполнять трахеотомию в сознании пациентам со значительным отеком гортани, особенно при его прогрессировании, с целью недопущения потери проходимости дыхательных путей из-за нарастания явлений стеноза [15, 21, 22, 28, 45]. 25  Уровень убедительности рекомендаций C (уровень достоверности доказательств – 4). Комментарий: на месте получения травмы допустимо введение трахеостомической трубки (любой полой трубки) через раневой канал в полость гортани или трахеи, выполнение кониотомии, крикотиреоидотомии с последующей заменой атипичной трахеостомы на типичную, с обязательным подшиванием трахеи к коже. Формирование стойкой стомы позволяет в любой момент поменять обтурированную слизью или выпавшую трахеостомическую трубку, не опасаясь смещения тканей и закрытия стомы, что особо важно на этапах медицинской эвакуации и в условиях боевых действий. По возможности следует избегать интубации, так как эндотрахеальная трубка может еще больше травмировать гортань, дестабилизировать переломы гортани или привести к острой травме дыхательных путей. Выполнение трахеотомии у детей рекомендовано только в условиях комбинированного ингаляционного наркоза"}, "t-dc": {"s": "ok", "sec": "3.2", "page": 25, "q": "Рекомендуется подходить к лечению пострадавших с тяжелыми ранениями и травмами шеи по принципу «Damage control surgery» (тактика контроля повреждения) для предупреждения развития неблагоприятного исхода ранений и травм [25, 33]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5). Комментарии: «Damage control surgery» (тактика контроля повреждения) запрограммированная многоэтапная хирургическая тактика, направленная на предупреждение развития неблагоприятного исхода ранений и травм, путем сокращения объема первого оперативного вмешательства и смещения окончательного восстановления поврежденных органов и структур до стабилизации жизненно важных функций организма. Хирургическое вмешательство на шее, как первый этап тактики \"damage control\" предусматривает: 1) устранение нарушений дыхания (асфиксии) путем интубации трахеи, выполнения типичной или атипичной трахеотомии; 2) временную или окончательную остановку кровотечения путем сосудистого шва, перевязки или тугой тампонады области повреждения кровеносных сосудов, а также временного протезирования общей и внутренней сонных артерий; 3) предотвращение дальнейшего инфицирования мягких тканей шеи содержимым полых органов (слизью, слюной) путем наложения швов или подведения мазевых тампонов к месту повреждения; 4) иммобилизацию шеи воротником Шанца ( шина –воротник) при ранении шейного отдела позвоночника. Интубация трахеи является стандартной процедурой неотложной медицины для установления и поддержания проходимости дыхательных путей. Иммобилизация шейного отдела позвоночника сохраняется во время выполнения неотложных процедур на дыхательных путях. Использоватьтрубку интубационную на один размер меньше предполагаемого, чтобы учесть отек гортани и предотвратить дальнейшее повреждение ее структур"}, "t-bleed": {"s": "ok", "sec": "3.2", "page": 24, "q": "Рекомендуется проводить хирургическое лечение пациентам с кровотечением из горла с целью его остановки [68, 69]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5). Комментарии: для остановки кровотечения применятся следующие манипуляции и хирургические вмешательства: тампонада раны, коагуляция кровоточащего сосуда, сшивание раны. В случае массивного некупируемого кровотечения проводятся эндоваскулярные окклюзирующие операции или перевязка сосуда (наружной сонной артерии). При обширном повреждении гортани, когда невозможно определить источник кровотечения, внутригортанном кровотечении прибегают к перевязке приводящих сосудов – верхней щитовидной или наружной сонной артерии, предварительно обезопасив дыхательные пути от аспирации крови путем проведения трахеотомии ниже места повреждения"}, "t-stop": {"s": "ok", "sec": "3.2", "page": 26, "q": "Рекомендуется принимать меры к устранению кровотечения (при его наличии) у всех пациентов в экстренном порядке с целью предупреждения геморрагического шока [21, 25, 28]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5). Комментарий: небольшие наружные кровотечения при ранениях гортани и трахеи останавливают наложением асептической давящей повязки и назначением гемостатических средств, при неэффективности (продолжающемся кровотечении) накладываются лигатуры на кровоточащий сосуд в ране."}, "t-pho": {"s": "ok", "sec": "3.2", "page": 26, "q": "Рекомендуется проводить хирургическую обработку раны , которая выполняется соответственно типу раны пациентам с ранениями гортани и глотки с целью предотвращения осложнений [21, 25, 28, 33] Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5). Комментарии: предлагаемый объем вмешательства соответственно типу раны. поверхностная рана – обработка, санация, наложение первичного кожного шва; глубокая рана с повреждением мягко-тканных структур – хирургическая обработка раны (рассечение, иссечение, восстановление поврежденных структур, 26  дренирование и наложение кожного шва, противовоспалительная и антибактериальная терапия); обширные скальпированные и размноженные раны – первичная хирургическая обработка раны и раневого дефекта, санация, первичная или отсроченная пластика дефекта кожного покрова, восстановление поврежденных структур, дренирование, кожные швы, противовоспалительная и антибактериальная терапия, трансфузионная терапия (по показаниям). Хирургическая обработка ран гортани должна быть экономной и производиться по возможности в ранние сроки. Удаляются легкодоступные инородные тела и только явно нежизнеспособные, размноженные мягкие ткани, слизистая оболочка гортани максимально сохраняется. Небольшие раны (до 0,5 см) гортани и трахеи могут не ушиваться и лечиться дренированием области повреждения."}, "t-nopho": {"s": "ok", "sec": "3.2", "page": 27, "q": "Не рекомендуется выполнение хирургической обработки раны у пациентов со поверхностными ранами, царапинами, ссадинами, небольших ран с расхождением краев менее 1 см, множественными мелкими ранами без повреждения мышц и фасциальных футляров, а также с колотыми ранами без повреждения внутренних органов, сосудов и нервов [15, 25]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5). Комментарии: при описанных выше типах ран проводится туалет раны без ПХО, в том числе (на выбор лечащего или дежурного врача) со сведением краев раны лейкопластырем медицинским или лейкопластырем (Лейко) фиксирующим медицинским без ее ушивания."}, "t-drain": {"s": "ok", "sec": "3.2", "page": 27, "q": "Рекомендуется выполнять хирургический дренаж раны доступными способами и средствами (установка раневого дренажа, перчаточного дренажа и иных) до прекращения образования отделяемого у всех пациентов с ранами с целью ускорения очищения раны"}, "t-nosuture": {"s": "ok", "sec": "3.2", "page": 27, "q": "Не рекомендуется ушивать рану при наличии признаков инфицирования раны и/или гнойно-воспалительных осложнений до купирования указанных процессов у всех 27  пациентов в целях профилактики дальнейшего развития раневой (в том числе анаэробной) инфекции"}, "t-fix": {"s": "ok", "sec": "3.2", "page": 28, "q": "Рекомендуется фиксировать любые переломы хрящей гортани со смещением у всех пациентов с переломами хрящей гортани с целью предупреждения дислокации хрящевых отломков [22, 47, 48]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5) Комментарии: фиксация позволяет свести к минимуму дислокацию отломков в послеоперационном периоде. Существует два взгляда при травмах гортани и трахеи на время проведения оперативного вмешательства: одни авторы советуют наиболее раннее выполнение вмешательства (в первые 24-48 часов) [9, 10, 49, 50], другие советуют отсрочить на неделю и более для уменьшения отека тканей [51, 52]. Повреждения шеи очень многообразны и в каждом конкретном случае надо рассматривать время вмешательства индивидуально, в зависимости от тяжести травмы и сопутствующей патологии."}, "t-thyreo": {"s": "ok", "sec": "3.2", "page": 28, "q": "Рекомендуется выполнять тиреоидотомию при разрыве слизистой оболочки двух и более анатомических областей, свободного края голосовых складок, переломах хрящевого каркаса [11, 22, 49, 51]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 4) Комментарии: данное вмешательство позволяет восстанавливать поврежденную слизистую оболочку и первично зашивать рваные раны голосовых складок рассасывающимся шовным материалом 5/0 или 6/0. Все открытые хрящи должны быть закрыты либо первично, либо с помощью местных лоскутов слизистой оболочки. Если перелом расположен более чем в 3 мм от передней комиссуры, все равно следует выполнить срединную тиреоидотомию."}, "t-aryt": {"s": "ok", "sec": "3.2", "page": 28, "q": "Рекомендуется восстанавливать смещенные или дислоцированные черпаловидные хрящи в зависимости от степени их повреждения [11, 22]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5). 28  Комментарии: изолированные рваные раны, затрагивающие эти хрящи, можно вылечить повторным их укрытием слизистой оболочкой. Полное смещение черпаловидных хрящей со суставной площадки перстневидного хряща требует травматического разрыва связок перстнечерпаловидного сустава."}, "t-ltp": {"s": "ok", "sec": "3.2", "page": 29, "q": "Рекомендуется производить ларинготрахеопластику местными тканями, предварительно выполнив типичную трахеотомию при проникающих ранениях гортани с повреждением хрящей и без значительного их смещения после ревизии раны с целью закрытия посттравматического дефекта [9, 11]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5). Комментарии: при необходимости операция выполняется комбинированным доступом, наружным и эндоскопическим (трансоральная микроларингоскопия) для оценки состояния просвета гортани, сохранности слизистой оболочки и возможности закрытия дефекта гортани без формирования ларингостомы. В просвет гортани на несколько дней устанавливается “пальчиковый перчаточный обтуратор фиксирующие нити которого выводятся наружу через трахеостомическое отверстие, впоследствии решается вопрос об необходимости и целесообразности установки эндопротеза."}, "t-stoma": {"s": "ok", "sec": "3.2", "page": 29, "q": "Рекомендуется формировать ларинготрахеостому всем пациентам при проникающих ранениях гортани со значительным разрушением и смещением хрящей, разрывами тканей в области передней комиссуры, выраженной рубцовой деформации просвета гортани после ревизии раны с целью предотвращения образования рубцовых образований [25, 28, 33]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5). Комментарии: в первые дни после операции просвет гортани тампонируют марлевым тампоном по Микуличу, пропитанным комбинированными препаратами в виде мази на основе хлорамфеникола (Код ATX: D06C антибиотики в комбинации с противомикробными средствами), с последующей его заменой на протез силиконовый для восстановления функции гортани [51-59,]; . множественные оскольчатые переломы скелета гортани часто требуют как внутреннего стентирования, так и внешней фиксации из-за движения гортани во время глотания; если переломы гортани можно стабилизировать без использования внутреннего фиксатора просвета, а повреждения слизистой оболочки гортани минимальны, следует избегать стентирования"}, "t-pexy": {"s": "ok", "sec": "3.2", "page": 30, "q": "Рекомендуется производить пластику гортани подшивание гортани за нижние рога подъязычной кости -ларингохиодеопексию) при переломах подъязычной кости, сопровождающихся отрывом гортани), произвоить пластику трахеи - подшивание трахеи к щитовидному хрящу - трахеоларингопексию)при отрыве гортани от трахеи с целью предупреждения осложнений [25, 28, 33]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5). Комментарии: после отрыва гортани от трахеи первая обычно вытягивается вверх, а трахея втягивается в положение за грудиной, что требует выполнения низкого трахеотомического разреза. Пневмоторакс обычно сопровождает отрыв гортани и требует своевременного выявления и лечения."}, "t-anest": {"s": "ok", "sec": "3.3", "page": 30, "q": "Рекомендуется применение местных анестетиков (Код АТХ: N01B) при выполнении хирургической обработки раны, манипуляциях в полости гортани (с учетом характеристик раны, выраженности болевого синдрома, а также аллергологического анамнеза пациентов) с целью обезболивания"}, "t-diet": {"s": "ok", "sec": "3.4", "page": 30, "q": "Рекомендуется общая восстановительная диета для всех пациентов, с достаточным количеством белков, жиров, углеводов, минеральных солей и витаминов, за исключением пациентов, имеющих заболевания терапевтического профиля, требующие соответствующей коррекции диеты (сахарный диабет и иные) [28]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5). Комментарий: в зависимости от наличия или отсутствия назогастрального зонда, гастростомы назначается энтеральное или парентеральное лечебное питание."}, "h-hosp": {"s": "ok", "sec": "6", "page": 33, "q": "Рекомендуется госпитализация пациентов с травмой гортани и глотки с целью наблюдения за проходимостью верхних дыхательных путей [22]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5). Комментарии: стационарное наблюдение следует проводить в течение 24-48 часов при легких травмах, которые могут прогрессировать или привести к повреждению дыхательных путей (отек, гематома), особенно у пациентов детского возраста [1, 2]. Также травма гортани у детей является опасным для жизни состоянием из-за риска возникновения кардиогенного шока вследствие брадикардии, аритмии, падения артериального давления или остановки сердца в связи с особенностями иннервации [37]. Более тяжелые травмы потребуют более длительного периода госпитализации и реабилитации. Небольшие, непрогрессирующие гематомы с неповрежденной слизистой оболочкой, скорее всего, разрешатся самостоятельно без серьезных последствий. Большие или увеличивающиеся гематомы могут привести к обструкции дыхательных путей и потребовать проведения трахеотомии."}, "h-org": {"s": "ok", "sec": "6", "page": 33, "q": "Все специалисты, оказывающие первую помощь как на догоспитальном, так и на госпитальном этапе, должны знать признаки обструкции дыхательных путей и владеть навыками поддержания дыхания пациента, обеспечивая при этом защиту шейного отдела позвоночника. Возможность успешного восстановления проходимости дыхательных путей увеличивается при наличии специального оборудования и навыков для его правильного и безопасного использования. На всех уровнях (догоспитальном, госпитальном) должны быть обеспечены гарантированные возможности для безопасного проведения манипуляций по восстановлению проходимости дыхательных путей (например, эндотрахеальная интубация, коникотомия, трахеотомия)"}, "r-follow": {"s": "ok", "sec": "4", "page": 31, "q": "Рекомендуется прием (осмотр, консультация) врача-оториноларинголога повторный в поликлинике по месту жительства, пациентам, перенесшим тупую травму шеи с повреждением гортани, гортаноглотки, а также пациентам, у которых была выполнена ларинготрахеопластика без формирования ларингостомы (ларинготрахеостомы) или уже было выполнено пластическое закрытие ларингостомы (ларинготрахеостомы) при нарушении голосовой функции показана консультация фониатра (фонопеда) с целью предупреждения и коррекции дисфонии"}, "r-follow-stoma": {"s": "ok", "sec": "4", "page": 31, "q": "Рекомендуется наблюдение врача-оториноларинголога стационара пациентам, у которых имелась открытая рана шеи с повреждением гортани и у которых была выполнена ларинготрахеопластика с формированием ларингостомы"}, "p-follow": {"s": "ok", "sec": "5", "page": 32, "q": "Рекомендуется прием (осмотр, консультация) врача-оториноларинголога повторный через 1 месяц, затем один раз в 3 месяца в течение года с целью своевременного выявления показаний для реконструктивной операции [ 9, 28]. . Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5). Комментарии: в ходе осмотров выполняется видеоларингоскопия гортани, проводится ларингоскопию с использованием стробоскопа ( ларингостробоскопическое исследование), определяется функция внешнего дыхания (по показаниям). Сроки проведения повторных хирургических вмешательств, направленных на деканюляцию (удаление трахеотомической трубки) и восстановление анатомической целостности, просвета гортани и трахеи, определяются индивидуально в зависимости от общего состояния пациента и клинико-функционального состояния полых органов шеи"}, "p-iatro": {"s": "ok", "sec": "5", "page": 31, "q": "Рекомендуется профилактика ятрогенной внутренней травмы гортани и гортаноглотки при проведении искусственной вентиляции легких (ИВЛ), эзофагогастродуоденоскопии (ЭГДС), бронхоскопии [28, 61, 63, 64]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5). 31  Комментарии: интубация трахеи, проведение фиброскопических исследований должны выполняться максимально аккуратно, без повреждения структур гортани. При затрудненной интубации рекомендуется применение видеоларингоскопа. Специфическая профилактика других видов травм гортани и глотки не разработана."}, "x-risk": {"s": "ok", "sec": "7", "page": 34, "q": "Факторы риска неблагоприятного исхода хирургического лечения: Системные факторы: пожилой возраст, иммунодефицитные состояния, кахексия, инфекция, онкологический процесс, нарушения углеводного обмена, коллагенозы и другие системные заболевания. Местные факторы: повреждение пищевода, сосудисто-нервного пучка шеи, позвоночника, гнойно-воспалительные изменения (флегмона шеи, медиастинит), повторная травма, инфекция, наличие инородных тел. Прогноз: при первичной пластике и восстановлении просвета гортани деформации органа с грубым нарушением его функции, как правило, не происходит. Однако, очень многое зависит от вида травмы, объема поврежденных структур гортани, индивидуальных особенностей и сопутствующей патологии. Повреждения гортани и трахеи относятся к тяжелым, калечащим травмам, зачастую приводящим к инвалидизации, а в связи с частым развитием вторичных рубцовых изменений могут потребовать проведения неоднократных реконструктивно-восстановительных операций, прогноз которых зачастую неизвестен."}}, "terms": {"a:НПВП": {"t": "НПВП", "q": "нестероидные противовоспалительные и противоревматические препараты", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])НПВП(?![\\w-])"}, "a:ПХО": {"t": "ПХО", "q": "первичная хирургическая обработка", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])ПХО(?![\\w-])"}, "a:ВХО": {"t": "ВХО", "q": "вторичная хирургическая обработка", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])ВХО(?![\\w-])"}, "a:ИВЛ": {"t": "ИВЛ", "q": "искусственная вентиляция легких", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])ИВЛ(?![\\w-])"}, "a:ЭГДС": {"t": "ЭГДС", "q": "эзофагогастродуоденоскопия", "sec": "Список сокращений", "page": 4, "re": "(?<![\\w-])ЭГДС(?![\\w-])"}, "d:Повреждение": {"t": "Повреждение", "q": "морфологический субстрат травмы (ранения). Имеет локальные морфологические проявления в виде сотрясений, ушибов, сдавлений, вывихов, переломов, ран, разрушений, отрывов, ожогов, отморожений, а также нарушений, обусловленных радиационными, химическими и другими воздействиями.", "sec": "Термины и определения", "page": 5, "re": "(?i:П)оврежден\\w*"}, "d:Рана": {"t": "Рана", "q": "частный вид повреждения. Открытая рана, затрагивающая гортань – это повреждение структур гортани, которое сопровождается нарушением целостности кожных покровов и/или слизистой оболочки на всю глубину, а часто и повреждение глубже расположенных тканей и органов.", "sec": "Термины и определения", "page": 5, "re": "(?i:Р)ан\\w*"}, "d:Кровотечение из горла": {"t": "Кровотечение из горла", "q": "истечение крови изо рта или попадание еѐ в дыхательные или пищепроводящие пути при наличии источника кровотечения, локализующегося в области ротоглотки, гортаноглотки и/или гортани. Уровень достоверности доказательств, УДД (англ. levels of evidence) – ранжирование дизайнов исследований, основываясь, прежде всего на их внутренней достоверности. Примечание 1: данный метод используется для определения убедительности исследования. Примечание: 2: различные иерархии доказательств используются для оценки технологий здравоохранения.", "sec": "Термины и определения", "page": 5, "re": "(?i:К)ровотечен\\w*\\s+из\\s+горл\\w*"}}};
